import json
from typing import Dict, List, Any

class Cart:
    def __init__(self):
        self.items = []

    def add_item(self, item_id: str, name: str, price: float, quantity: int = 1):
        for item in self.items:
            if item['id'] == item_id:
                item['quantity'] += quantity
                return
        self.items.append({'id': item_id, 'name': name, 'price': price, 'quantity': quantity})

    def remove_item(self, item_id: str):
        self.items = [item for item in self.items if item['id'] != item_id]

    def get_total(self) -> float:
        return sum(item['price'] * item['quantity'] for item in self.items)

    def clear(self):
        self.items.clear()

# 模擬數據存儲
cart = Cart()
orders: List[Dict[str, Any]] = []
menu_items = [
    {'id': '1', 'name': '燕麥粥', 'price': 25.0, 'image': 'oatmeal.jpg'},
    {'id': '2', 'name': '吐司配果醬', 'price': 30.0, 'image': 'toast.jpg'},
    {'id': '3', 'name': '煎蛋三明治', 'price': 40.0, 'image': 'sandwich.jpg'},
    {'id': '4', 'name': '咖啡', 'price': 20.0, 'image': 'coffee.jpg'},
    {'id': '5', 'name': '果汁', 'price': 25.0, 'image': 'juice.jpg'}
]

# 獲取菜單
async def get_menu() -> List[Dict[str, Any]]:
    return menu_items

# 提交訂單
async def create_order(customer_name: str, customer_phone: str, items: List[Dict[str, Any]]) -> Dict[str, Any]:
    order_id = len(orders) + 1
    total = sum(item['price'] * item['quantity'] for item in items)
    order = {
        'id': order_id,
        'customer_name': customer_name,
        'customer_phone': customer_phone,
        'items': items,
        'total': total,
        'status': 'pending'
    }
    orders.append(order)
    cart.clear()
    return order

# 獲取訂單列表
async def get_orders() -> List[Dict[str, Any]]:
    return orders

# 獲取特定訂單詳情
async def get_order(order_id: int) -> Dict[str, Any]:
    for order in orders:
        if order['id'] == order_id:
            return order
    return {}

def handle(method: str, path: str, body: bytes) -> tuple[int, dict]:
    try:
        if method == 'GET' and path == '/menu':
            return (200, {'items': menu_items})

        elif method == 'POST' and path == '/cart/add':
            data = json.loads(body)
            item_id = data.get('id')
            name = data.get('name')
            price = data.get('price')
            quantity = data.get('quantity', 1)

            if not all([item_id, name, price]):
                return (400, {'error': '缺少必要字段'})

            cart.add_item(item_id, name, price, quantity)
            return (200, {'message': '菜品已添加到購物車'})

        elif method == 'DELETE' and path == '/cart/remove':
            data = json.loads(body)
            item_id = data.get('id')

            if not item_id:
                return (400, {'error': '缺少菜品ID'})

            cart.remove_item(item_id)
            return (200, {'message': '菜品已從購物車刪除'})

        elif method == 'GET' and path == '/cart':
            return (200, {'items': cart.items, 'total': cart.get_total()})

        elif method == 'POST' and path == '/order':
            data = json.loads(body)
            customer_name = data.get('customer_name')
            customer_phone = data.get('customer_phone')
            items = data.get('items', [])

            if not all([customer_name, customer_phone, items]):
                return (400, {'error': '缺少必要字段'})

            order = create_order(customer_name, customer_phone, items)
            return (201, {'order': order})

        elif method == 'GET' and path == '/orders':
            return (200, {'orders': orders})

        elif method == 'GET' and path.startswith('/order/'):
            try:
                order_id = int(path.split('/')[-1])
                order = get_order(order_id)
                if not order:
                    return (404, {'error': '訂單不存在'})
                return (200, {'order': order})
            except ValueError:
                return (400, {'error': '無效的訂單ID'})

        else:
            return (404, {'error': '路徑不存在'})
    except json.JSONDecodeError:
        return (400, {'error': '無效的JSON數據'})
    except Exception as e:
        return (500, {'error': '服務器內部錯誤'})

