document.addEventListener('DOMContentLoaded', () => {
  const menuSection = document.getElementById('menu-section');
  const cartSection = document.getElementById('cart-section');
  const orderFormSection = document.getElementById('order-form-section');
  const ordersSection = document.getElementById('orders-section');

  // DOM 元素
  const menuItemsContainer = document.getElementById('menu-items');
  const cartItemsContainer = document.getElementById('cart-items');
  const cartTotalElement = document.getElementById('cart-total');
  const checkoutBtn = document.getElementById('checkout-btn');
  const orderForm = document.getElementById('order-form');
  const ordersListContainer = document.getElementById('orders-list');

  // 狀態
  let menuItems = [];
  let cartItems = [];

  // 獲取菜單
  async function fetchMenu() {
    try {
      const response = await fetch('api/menu');
      if (!response.ok) {
        throw new Error(`獲取菜單失敗: ${response.status} ${response.statusText}`);
      }
      menuItems = await response.json();
      renderMenu();
    } catch (error) {
      showError('獲取菜單失敗', error.message);
    }
  }

  // 獲取購物車內容
  async function fetchCart() {
    try {
      const response = await fetch('api/cart');
      if (!response.ok) {
        throw new Error(`獲取購物車失敗: ${response.status} ${response.statusText}`);
      }
      cartItems = await response.json();
      renderCart();
    } catch (error) {
      showError('獲取購物車失敗', error.message);
    }
  }

  // 獲取訂單列表
  async function fetchOrders() {
    try {
      const response = await fetch('api/orders');
      if (!response.ok) {
        throw new Error(`獲取訂單列表失敗: ${response.status} ${response.statusText}`);
      }
      const orders = await response.json();
      renderOrders(orders);
    } catch (error) {
      showError('獲取訂單列表失敗', error.message);
    }
  }

  // 渲染菜單
  function renderMenu() {
    menuItemsContainer.innerHTML = '';
    menuItems.forEach(item => {
      const itemElement = document.createElement('div');
      itemElement.className = 'menu-item';
      itemElement.innerHTML = `
        <h3>${item.name}</h3>
        <p>價格: $${item.price}</p>
        <button onclick="addToCart('${item.id}')">加入購物車</button>
      `;
      menuItemsContainer.appendChild(itemElement);
    });
  }

  // 渲染購物車
  function renderCart() {
    cartItemsContainer.innerHTML = '';
    let total = 0;

    cartItems.forEach(item => {
      const itemTotal = item.price * item.quantity;
      total += itemTotal;

      const itemElement = document.createElement('div');
      itemElement.className = 'cart-item';
      itemElement.innerHTML = `
        <span>${item.name} x ${item.quantity}</span>
        <span>$${itemTotal}</span>
        <button onclick="removeFromCart('${item.id}')">刪除</button>
      `;
      cartItemsContainer.appendChild(itemElement);
    });

    cartTotalElement.textContent = `總計: $${total}`;
  }

  // 加入購物車
  async function addToCart(itemId) {
    try {
      const response = await fetch('api/cart/add', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ item_id: itemId }),
      });
      if (!response.ok) {
        throw new Error(`加入購物車失敗: ${response.status} ${response.statusText}`);
      }
      await fetchCart(); // 重新獲取購物車
    } catch (error) {
      showError('加入購物車失敗', error.message);
    }
  }

  // 從購物車刪除
  async function removeFromCart(itemId) {
    try {
      const response = await fetch('api/cart/remove', {
        method: 'DELETE',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ item_id: itemId }),
      });
      if (!response.ok) {
        throw new Error(`從購物車刪除失敗: ${response.status} ${response.statusText}`);
      }
      await fetchCart(); // 重新獲取購物車
    } catch (error) {
      showError('從購物車刪除失敗', error.message);
    }
  }

  // 提交訂單
  async function submitOrder(orderData) {
    try {
      const response = await fetch('api/order', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify(orderData),
      });
      if (!response.ok) {
        throw new Error(`提交訂單失敗: ${response.status} ${response.statusText}`);
      }
      const result = await response.json();
      alert('訂單提交成功！');
      // 重置購物車
      cartItems = [];
      renderCart();
      // 顯示訂單列表
      showOrders();
      fetchOrders(); // 獲取最新的訂單列表
    } catch (error) {
      showError('提交訂單失敗', error.message);
    }
  }

  // 顯示訂單列表
  function showOrders() {
    menuSection.classList.add('hidden');
    cartSection.classList.add('hidden');
    orderFormSection.classList.add('hidden');
    ordersSection.classList.remove('hidden');
  }

  // 顯示結帳頁面
  function showCheckout() {
    menuSection.classList.add('hidden');
    cartSection.classList.remove('hidden');
    orderFormSection.classList.remove('hidden');
    ordersSection.classList.add('hidden');
  }

  // 顯示錯誤訊息
  function showError(title, message) {
    alert(`${title}: ${message}`);
  }

  // 初始化
  fetchMenu();
  fetchCart();

  // 綁定事件
  checkoutBtn.addEventListener('click', showCheckout);

  orderForm.addEventListener('submit', (e) => {
    e.preventDefault();
    const customerName = document.getElementById('customer-name').value;
    const customerPhone = document.getElementById('customer-phone').value;
    const customerAddress = document.getElementById('customer-address').value;

    submitOrder({
      customer_name: customerName,
      customer_phone: customerPhone,
      customer_address: customerAddress,
      items: cartItems.map(item => ({
        item_id: item.id,
        quantity: item.quantity
      }))
    });
  });
});

